vec2 ab = b - a;
vec2 ac = c - a;
vec2 ap = p - a;

double det = ab.x * ac.y - ab.y * ac.x;

if (std::abs(det) < 1e-6) {
    return {-1, -1, -1}; // degenerate triangle
}

double inv_det = 1.0 / det;
vec3 result;

result[1] = (ac.y * ap.x - ac.x * ap.y) * inv_det;
result[2] = (ab.x * ap.y - ab.y * ap.x) * inv_det;
result[0] = 1.0 - result[1] - result[2];

return result;

